export interface GetPlaybackQuery {
	/** Video codecs the client decodes beyond the h264/vp9/av1 baseline (e.g. hevc), for the direct-play decision. */
	caps?: string[];
}

/** `GET /playback/{kind}/{id}` */
export const getPlayback = (kind: GetPlaybackKind, id: string, query: GetPlaybackQuery = {}) =>
	api<PlaybackInfo>(`/playback/${encodeURIComponent(kind)}/${encodeURIComponent(id)}${qs({ caps: query.caps?.join(',') })}`);

